.ds-almanac { --ds-cover-bg: var(--ds-paper); --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-ink); --ds-hand-fill2: var(--ds-accent); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-card); --ds-hand-stroke: 1.5; --ds-hand-cap: round; --ds-hand-shadow: #b44e3020; --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 1px solid var(--ds-line); --ds-tpl-radius: 0; --ds-tpl-rule: 1px solid var(--ds-line); --ds-tpl-tile-shadow: none; --ds-tag-radius: 0;
  --ds-slide-bg: var(--ds-paper); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-band); --ds-slide-title-fg: var(--ds-ink); --ds-slide-split-a: var(--ds-ink); --ds-slide-split-a-fg: var(--ds-paper); --ds-slide-split-b: var(--ds-accent); --ds-slide-split-b-fg: var(--ds-on-accent); --ds-hero-bg: var(--ds-band); }
.dark .ds-almanac { --ds-hand-shadow: #e07a5826; }
.ds-almanac .ds-cover-name, .ds-almanac .ds-section h2 { font-weight: 400; }
.ds-almanac .ds-chip { font-family: var(--font-mono); font-weight: 400; border-color: var(--ds-line); }
.ds-almanac .ds-principle-n { font-family: var(--font-display); font-weight: 400; font-size: 40px; letter-spacing: -.05em; color: var(--ds-accent); }
.ds-almanac .ds-tpl-slide-h, .ds-almanac .ds-tpl-hero-h, .ds-almanac .ds-tpl-ed-h, .ds-almanac .ds-tpl-brand, .ds-almanac .ds-tpl-slide-big, .ds-almanac .ds-tpl-dropcap { font-weight: 400; letter-spacing: -.05em; }
.ds-almanac .ds-tpl-brand { letter-spacing: -.07em; font-family: var(--font-body); font-weight: 600; font-size: 22px; text-transform: lowercase; }
.ds-almanac .h-num { font-weight: 400; letter-spacing: -.06em; font-size: 48px; }
.ds-almanac .al-paper { fill: var(--ds-paper); } .ds-almanac .al-card { fill: var(--ds-card); stroke: var(--ds-line); stroke-width: 1; }
.ds-almanac .al-band { fill: var(--ds-band); } .ds-almanac .al-shadow { fill: var(--ds-hand-shadow); }
.ds-almanac .al-fill { fill: var(--ds-hand-fill, var(--ds-ink)); } .ds-almanac .al-fill2 { fill: var(--ds-hand-fill2, var(--ds-accent)); } .ds-almanac .al-muted { fill: var(--ds-hand-muted, var(--ds-paper-sunk)); } .ds-almanac .al-outline { fill: none; stroke: var(--ds-hand-ink, var(--ds-ink)); stroke-width: 1.2; }
.ds-almanac .al-line { stroke: var(--ds-line); stroke-width: 1; }
.ds-almanac .al-num { font-family: var(--font-display); font-size: 84px; letter-spacing: -.07em; fill: var(--ds-hand-ink, var(--ds-ink)); } .ds-almanac .al-mono { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: .06em; fill: var(--ds-hand-ink, var(--ds-ink)); }
.ds-almanac .al-serif-i { font-family: var(--font-display); font-style: italic; font-size: 20px; letter-spacing: -.02em; fill: var(--ds-hand-ink, var(--ds-ink)); } .ds-almanac .al-serif-t { font-family: var(--font-display); font-size: 26px; letter-spacing: -.03em; fill: var(--ds-ink); }
.ds-almanac .al-btn-o { fill: none; stroke: var(--ds-hand-ink, var(--ds-ink)); stroke-width: 1; } .ds-almanac .al-btn-f { fill: var(--ds-hand-ink, var(--ds-ink)); } .ds-almanac .al-on-fill { fill: var(--ds-paper); }
.ds-almanac .al-btn { display: inline-flex; align-items: center; justify-content: space-between; gap: 30px; padding: 15px 22px; border: 1px solid currentColor; background: transparent; color: inherit; font-family: var(--font-mono); font-size: 12px; letter-spacing: .06em; text-transform: uppercase; line-height: 1; cursor: pointer; transition: background 200ms, color 200ms, transform 200ms; }
.ds-almanac .al-btn:hover { background: var(--ds-ink); color: var(--ds-paper); transform: translateY(-2px); }
.ds-almanac .al-btn:focus-visible { outline: 3px solid var(--ds-accent); outline-offset: 6px; }
.ds-almanac .al-btn-fill { background: var(--ds-accent); border-color: var(--ds-accent); color: var(--ds-on-accent); } .ds-almanac .al-btn-fill:hover { background: var(--ds-ink); border-color: var(--ds-ink); }
.ds-almanac .al-tag { display: inline-flex; align-items: center; gap: 6px; padding: 7px 11px; border: 1px solid var(--ds-line); font-family: var(--font-mono); font-size: 10px; letter-spacing: .06em; text-transform: uppercase; line-height: 1; color: var(--ds-ink); }
.ds-almanac .al-tag-ink { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-paper); } .ds-almanac .al-tag-accent { background: var(--ds-accent); border-color: var(--ds-accent); color: var(--ds-on-accent); } .ds-almanac .al-tag-positive { background: var(--ds-positive-soft); border-color: var(--ds-positive-soft); color: var(--ds-positive); }
.ds-almanac .al-outcome { border-top: 1px solid var(--ds-line); padding-top: 22px; display: grid; gap: 12px; align-content: start; min-width: 0; }
.ds-almanac .al-outcome h3 { margin: 0; } .ds-almanac .al-outcome p { margin: 0; color: var(--ds-ink-muted); }
.ds-almanac .al-accent { color: var(--ds-accent); } .ds-almanac .al-mauve { color: var(--ds-mauve); } .ds-almanac .al-muted { color: var(--ds-ink-muted); }
.ds-almanac .ds-stats { gap: 40px; align-items: start; }
.ds-almanac .al-callout { padding: 16px 0; border-top: 1px solid var(--ds-line); border-bottom: 1px solid var(--ds-line); line-height: 1.6; font-size: 16px; } .ds-almanac .al-callout strong { font-weight: 500; }
.ds-almanac .al-callout-positive { background: var(--ds-positive-soft); padding: 16px 18px; border: 0; } .ds-almanac .al-callout-negative { background: var(--ds-negative-soft); padding: 16px 18px; border: 0; }
.ds-almanac .al-ticket { background: var(--ds-card); border: 1px solid var(--ds-line); padding: 32px 30px; max-width: 520px; display: grid; gap: 6px; }
.ds-almanac .al-ticket h3 { margin: 0; } .ds-almanac .al-ticket p { margin: 0; }
.ds-almanac .al-ticket-details { display: flex; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid var(--ds-line); } .ds-almanac .al-ticket-details + .al-ticket-details { border-top: 0; margin-top: -8px; border-bottom: 1px solid var(--ds-line); margin-bottom: 14px; }
.ds-almanac .al-sample { background: var(--ds-paper); }
.ds-almanac .al-nav { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 25px 20px; border-bottom: 1px solid var(--ds-line); }
.ds-almanac .al-wordmark { font-family: var(--font-body); font-size: 23px; font-weight: 600; letter-spacing: -.07em; }
.ds-almanac .al-hero { position: relative; display: grid; gap: 40px; padding: 56px 20px 72px; background: var(--ds-band); }
.ds-almanac .al-hero-h { margin: 0; max-width: 11ch; } .ds-almanac .al-hero-h em { color: var(--ds-accent); }
.ds-almanac .al-hero-p { margin: 28px 0 0; max-width: 400px; font-size: 17px; }
.ds-almanac .al-scroll { margin-top: 36px; border: 0; border-bottom: 1px solid currentColor; padding: 0 0 12px; gap: 40px; } .ds-almanac .al-scroll:hover { background: transparent; color: inherit; transform: none; }
.ds-almanac .al-arch { position: relative; justify-self: center; width: min(100%, 360px); padding: 56px 28px 36px; background: var(--ds-screen); border-radius: 180px 180px 0 0; box-shadow: var(--ds-shadow-soft); display: grid; place-items: center; text-align: center; transform: rotate(-3deg); transition: transform 500ms; }
.ds-almanac .al-arch:hover { transform: rotate(0deg) translateY(-8px); }
.ds-almanac .al-device { display: grid; gap: 10px; justify-items: center; }
.ds-almanac .al-device-n { font-size: clamp(72px, 10vw, 115px); line-height: 1; }
.ds-almanac .al-device-m { font-size: 22px; line-height: 1.1; letter-spacing: -.04em; max-width: 14ch; }
.ds-almanac .al-hero-cap { display: flex; justify-content: space-between; gap: 25px; grid-column: 1 / -1; color: var(--ds-ink-muted); }
.ds-almanac .al-outcomes { display: grid; gap: 40px; padding: 56px 20px 0; }
.ds-almanac .al-breakdown { padding: 56px 20px 72px; }
.ds-almanac .al-total-bar { display: flex; height: 96px; border-radius: 70px 70px 0 0; overflow: hidden; }
.ds-almanac .al-total-bar span { display: flex; align-items: center; padding: 20px; font-size: 48px; letter-spacing: -.06em; }
.ds-almanac .al-r60 { width: 60%; background: var(--ds-ink); color: var(--ds-paper); } .ds-almanac .al-r25 { width: 25%; background: var(--ds-accent); color: var(--ds-on-accent); } .ds-almanac .al-r15 { width: 15%; background: var(--ds-mauve); color: var(--ds-paper); }
.ds-almanac .al-eq { margin: 24px 0 0; color: var(--ds-ink-muted); }
.ds-almanac .ds-tpl-tag.is-idle { background: var(--ds-paper-sunk); }
.ds-almanac .ds-tpl-figure, .ds-almanac .ds-tpl-hero-art { border-radius: 180px 180px 0 0; padding: 40px 24px 16px; background: var(--ds-screen); box-shadow: var(--ds-shadow-soft-sm); }
.ds-almanac .ds-tpl-hero-art { background: var(--ds-screen); }
.ds-almanac .ds-tpl-kpi, .ds-almanac .ds-tpl-tile, .ds-almanac .ds-tpl-step { border: 0; border-top: 1px solid var(--ds-line); background: transparent; padding-left: 0; padding-right: 0; }
.ds-almanac .ds-tpl-stage-title .ds-tpl-stage-foot { border-top-color: var(--ds-ink); }
@container (min-width: 760px) {
  .ds-almanac .al-nav { padding: 25px 40px; }
  .ds-almanac .al-hero { grid-template-columns: 1.25fr 1fr; align-items: center; padding: 72px 40px 80px; }
  .ds-almanac .al-arch { transform: rotate(-6deg); }
  .ds-almanac .al-outcomes { grid-template-columns: 1fr 1fr 1fr; padding: 72px 40px 0; }
  .ds-almanac .al-breakdown { padding: 64px 40px 80px; }
}
@container (max-width: 440px) {
  .ds-almanac .al-band.al-arch { transform: none; }
  .ds-almanac .al-band.al-arch:hover { transform: none; }
}
